<?php require '../config.php';requireAdmin();$message='';$error='';
if($_SERVER['REQUEST_METHOD']==='POST'&&!csrf_ok($_POST['csrf']??''))$error='Security check failed.';
elseif($_SERVER['REQUEST_METHOD']==='POST'){$a=$_POST['action']??'';if($a==='stock'){$id=(int)$_POST['id'];$stock=max(0,(int)$_POST['stock']);$q=$conn->prepare('UPDATE products SET stock=? WHERE id=?');$q->bind_param('ii',$stock,$id);$q->execute();$message='Stock updated.';}elseif($a==='order'){$id=(int)$_POST['id'];$status=$_POST['status']??'Pending';$allowed=['Pending','Processing','Shipped','Completed','Cancelled'];if(in_array($status,$allowed,true)){$q=$conn->prepare('UPDATE orders SET status=? WHERE id=?');$q->bind_param('si',$status,$id);$q->execute();$message='Order status updated.';}}elseif($a==='delete_product'){$id=(int)$_POST['id'];$q=$conn->prepare('DELETE FROM products WHERE id=?');$q->bind_param('i',$id);if($q->execute())$message='Product deleted.';else $error='Product cannot be deleted if it belongs to an order.';}elseif($a==='role'){$id=(int)$_POST['id'];$role=$_POST['role']==='admin'?'admin':'user';$q=$conn->prepare('UPDATE users SET role=? WHERE id=?');$q->bind_param('si',$role,$id);$q->execute();$message='User role updated.';}}
$products=$conn->query('SELECT * FROM products ORDER BY id DESC');$orders=$conn->query('SELECT o.*,u.name,u.email FROM orders o JOIN users u ON u.id=o.user_id ORDER BY o.id DESC');$users=$conn->query('SELECT id,name,email,role,created_at FROM users ORDER BY id DESC');$countProducts=$conn->query('SELECT COUNT(*) c FROM products')->fetch_assoc()['c'];$countOrders=$conn->query('SELECT COUNT(*) c FROM orders')->fetch_assoc()['c'];$countUsers=$conn->query('SELECT COUNT(*) c FROM users')->fetch_assoc()['c'];
?><!DOCTYPE html><html><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Admin Dashboard | Ceylon Noir</title><link rel="stylesheet" href="admin.css"></head><body><header><a href="../index.php" class="logo">✦ CEYLON NOIR <small>ADMIN CONSOLE</small></a><nav><a href="../index.php">Store</a><a href="../profile.php">My Profile</a><a href="../logout.php">Logout</a></nav></header><main><div class="top"><div><span>CONTROL CENTER</span><h1>Admin Dashboard</h1><p>Full management access for the Ceylon Noir e-commerce system.</p></div></div><?php if($message):?><div class="ok"><?php echo e($message);?></div><?php endif;?><?php if($error):?><div class="err"><?php echo e($error);?></div><?php endif;?><div class="stats"><div><small>PRODUCTS</small><b><?php echo $countProducts;?></b></div><div><small>ORDERS</small><b><?php echo $countOrders;?></b></div><div><small>USERS</small><b><?php echo $countUsers;?></b></div></div><section class="admin-card"><h2>Product & Stock Management</h2><table><tr><th>Product</th><th>Category</th><th>Price</th><th>Stock</th><th>Action</th></tr><?php while($p=$products->fetch_assoc()):?><tr><td><?php echo e($p['name']);?></td><td><?php echo e($p['category']);?></td><td>Rs. <?php echo number_format($p['price'],2);?></td><td><form class="inline" method="post"><input type="hidden" name="csrf" value="<?php echo e(csrf_token());?>"><input type="hidden" name="action" value="stock"><input type="hidden" name="id" value="<?php echo $p['id'];?>"><input type="number" name="stock" min="0" value="<?php echo $p['stock'];?>"><button>Save</button></form></td><td><form method="post" onsubmit="return confirm('Delete this product?')"><input type="hidden" name="csrf" value="<?php echo e(csrf_token());?>"><input type="hidden" name="action" value="delete_product"><input type="hidden" name="id" value="<?php echo $p['id'];?>"><button class="danger">Delete</button></form></td></tr><?php endwhile;?></table></section><section class="admin-card"><h2>Order Management</h2><table><tr><th>Order</th><th>Customer</th><th>Total</th><th>Status</th><th>Update</th></tr><?php while($o=$orders->fetch_assoc()):?><tr><td>#<?php echo $o['id'];?><br><small><?php echo e($o['created_at']);?></small></td><td><?php echo e($o['name']);?><br><small><?php echo e($o['email']);?></small></td><td>Rs. <?php echo number_format($o['total'],2);?></td><td><span class="badge"><?php echo e($o['status']);?></span></td><td><form class="inline" method="post"><input type="hidden" name="csrf" value="<?php echo e(csrf_token());?>"><input type="hidden" name="action" value="order"><input type="hidden" name="id" value="<?php echo $o['id'];?>"><select name="status"><option>Pending</option><option>Processing</option><option>Shipped</option><option>Completed</option><option>Cancelled</option></select><button>Update</button></form></td></tr><?php endwhile;?></table></section><section class="admin-card"><h2>User Management</h2><table><tr><th>User</th><th>Email</th><th>Role</th><th>Joined</th><th>Change Access</th></tr><?php while($u=$users->fetch_assoc()):?><tr><td><?php echo e($u['name']);?></td><td><?php echo e($u['email']);?></td><td><span class="badge"><?php echo e($u['role']);?></span></td><td><?php echo e(date('d M Y',strtotime($u['created_at'])));?></td><td><form class="inline" method="post"><input type="hidden" name="csrf" value="<?php echo e(csrf_token());?>"><input type="hidden" name="action" value="role"><input type="hidden" name="id" value="<?php echo $u['id'];?>"><select name="role"><option value="user" <?php echo $u['role']==='user'?'selected':'';?>>User</option><option value="admin" <?php echo $u['role']==='admin'?'selected':'';?>>Admin</option></select><button>Save</button></form></td></tr><?php endwhile;?></table></section></main></body></html>
